async function resolveModule(module: Type<any>, registry: Map<Type, Module>, resolving = new Set<Type>()): Promise<Module> {
    if (resolving.has(module)) {
        throw new CircularDependencyException(module.name);
    }
    if (registry.has(module)) {
        return registry.get(module)!;
    }
    resolving.add(module);
    const imports = Reflect.getMetadata('imports', module) || [];
    const resolved = new Module(module);
    registry.set(module, resolved);
    for (const imp of imports) {
        const child = await resolveModule(imp, registry, resolving);
        resolved.addImport(child);
    }
    resolving.delete(module);
    return resolved;
}

