function mapResults(rows: any[], modelFields: Field[], includeFields: IncludeField[]): any[] {
    const seen = new Map<string, any>();
    for (const row of rows) {
        const pk = row[modelFields.find(f => f.isPrimaryKey)!.columnName];
        if (!seen.has(pk)) {
            const obj: any = {};
            for (const field of modelFields) {
                obj[field.name] = row[field.columnName];
            }
            for (const inc of includeFields) {
                obj[inc.name] = [];
            }
            seen.set(pk, obj);
        }
        const parent = seen.get(pk)!;
        for (const inc of includeFields) {
            const child = mapRelation(row, inc);
            if (child) parent[inc.name].push(child);
        }
    }
    return Array.from(seen.values());
}

