static void validateFieldMapping(MappedFieldType existingField, MappedFieldType newField) {
    if (!existingField.typeName().equals(newField.typeName())) {
        // Allow multi-field type coexistence (e.g., text + keyword)
        if (isMultiFieldCompatible(existingField, newField)) {
            return;
        }
        throw new MapperParsingException(
            "mapper [" + existingField.name() + "] cannot be changed from type [" +
            existingField.typeName() + "] to [" + newField.typeName() + "]"
        );
    }
}

static boolean isMultiFieldCompatible(MappedFieldType a, MappedFieldType b) {
    return a.name().contains(".") || b.name().contains(".");
}

