func getNextScheduleTime(cj *batchv1.CronJob, now time.Time, existingJobs []*batchv1.Job) []time.Time {
    sched, _ := cron.ParseStandard(cj.Spec.Schedule)
    var scheduledTimes []time.Time
    t := cj.Status.LastScheduleTime.Time
    for t.Before(now) {
        t = sched.Next(t)
        if !isJobAlreadyCreated(t, existingJobs) {
            scheduledTimes = append(scheduledTimes, t)
        }
    }
    // Limit to most recent 100 missed times to prevent thundering herd
    if len(scheduledTimes) > 100 {
        scheduledTimes = scheduledTimes[len(scheduledTimes)-100:]
    }
    return scheduledTimes
}

