function narrowTypeBySwitchOnDiscriminant(type, switchStatement, clauseIndex) {
    const clauseTypes: Type[] = [];
    // Walk backwards to collect all fallthrough case types
    for (let i = clauseIndex; i >= 0; i--) {
        const clause = switchStatement.clauses[i];
        if (clause.kind === SyntaxKind.CaseClause) {
            clauseTypes.push(getTypeOfExpression(clause.expression));
        }
        if (i < clauseIndex && clauseHasBreak(switchStatement.clauses[i])) {
            break;
        }
    }
    return filterType(type, t => clauseTypes.some(ct => isTypeComparableTo(t, ct)));
}

